import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.B_zcDAFh.js";const g=JSON.parse('{"title":"Boing Behavior","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-behavior.md","filePath":"guide/boing-behavior.md"}'),i={name:"guide/boing-behavior.md"};function n(s,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="boing-behavior" tabindex="-1">Boing Behavior <a class="header-anchor" href="#boing-behavior" aria-label="Permalink to &quot;Boing Behavior&quot;">​</a></h1><p>Attach <strong>Boing Behavior</strong> to a GameObject and its rendered transform will spring toward the target position and rotation you set, rather than snapping to it. Move or rotate the object however you like — the bouncy lag is applied for you each frame.</p><p>The component reads the transform you set during <code>Update</code> (or <code>FixedUpdate</code>), then writes a spring-smoothed version back during the matching late phase for rendering, and restores your original value before the next frame.</p><h2 id="typical-use" tabindex="-1">Typical Use <a class="header-anchor" href="#typical-use" aria-label="Permalink to &quot;Typical Use&quot;">​</a></h2><p>Drive the transform from input, scripts, tweens, or animations — anything. As long as it&#39;s set during the frame&#39;s logic phase, the spring response shows up automatically. A mouse-followed object, for example, will lag behind the cursor and settle when it stops.</p><h2 id="inspector-at-a-glance" tabindex="-1">Inspector at a Glance <a class="header-anchor" href="#inspector-at-a-glance" aria-label="Permalink to &quot;Inspector at a Glance&quot;">​</a></h2><ul><li><strong>Update Mode</strong> — <code>LateUpdate</code> (default, variable <code>Time.deltaTime</code>), <code>EarlyUpdate</code> (apply at end of <code>Update</code>, for renderers that read transforms early), or <code>FixedUpdate</code> (fixed <code>Time.fixedDeltaTime</code>; use this if a Rigidbody drives the object).</li><li><strong>Enable Position / Rotation / Scale Effect</strong> — toggle which channels bounce. Scale is off by default.</li><li><strong>Translation / Rotation Lock</strong> — eliminate spring effect on selected axes, in global or local space.</li><li><strong>Params / Shared Params</strong> — local spring tuning, or point at a <a href="./shared-boing-params.html">Shared Boing Params</a> asset to drive many components from one place.</li></ul><h2 id="avoiding-sudden-jumps-after-teleports" tabindex="-1">Avoiding Sudden Jumps After Teleports <a class="header-anchor" href="#avoiding-sudden-jumps-after-teleports" aria-label="Permalink to &quot;Avoiding Sudden Jumps After Teleports&quot;">​</a></h2><p>When you intentionally snap the object to a new pose, call <code>BoingBehavior.HandleTeleport()</code> immediately afterward. This resets the spring so the teleport isn&#39;t interpreted as a huge instantaneous velocity.</p><p>See the <a href="/boing-kit/api/boing-behavior.html">API reference</a> for the full property list.</p>',10)])])}const u=a(i,[["render",n]]);export{g as __pageData,u as default};
